import React, { useState, useEffect } from 'react';
import { getFranchises, updateExamData, deleteExamData } from '../services/api'; // Ensure deleteExamData is available

const ExamData = () => {
  const [filterFranchiseId, setFilterFranchiseId] = useState(''); // State to store the selected filter
  const [franchises, setFranchises] = useState([]); // Store the list of franchises
  const [examDataList, setExamDataList] = useState([]); // Store the list of exam data

  // Fetch franchises and their exam data on component mount
  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        console.log(response.data);  // Log the full response to verify the structure
        setFranchises(response.data); // Assuming the response contains an array of franchises
      } catch (error) {
        console.error('Error fetching franchises:', error);
        alert('Failed to fetch franchises');
      }
    };

    fetchFranchises();
  }, []); // Run once when the component mounts

  // Filter exam data based on selected franchise
  const filteredExamData = filterFranchiseId
    ? examDataList.filter((exam) => exam.franchiseId === filterFranchiseId)
    : examDataList;

  // Get the exam data for the selected franchise
  const getFranchiseExams = (franchiseId) => {
    const franchise = franchises.find((f) => f._id === franchiseId);
    return franchise ? franchise.examData : [];
  };

  // Get franchise name based on the ID
  const getFranchiseName = (id) => {
    const franchise = franchises.find((f) => f._id === id);
    return franchise ? franchise.name : 'Unknown Franchise';
  };

  // Handle delete exam
  const handleDeleteExam = async (examId) => {
    try {
      await deleteExamData(examId);
      setExamDataList(examDataList.filter(exam => exam._id !== examId)); // Remove from the list
      alert('Exam deleted successfully');
    } catch (error) {
      console.error('Error deleting exam:', error);
      alert('Failed to delete exam');
    }
  };

  // Handle edit exam
  const handleEditExam = (examId) => {
    // Redirect to an edit page or open a modal to edit the exam data
    console.log('Edit exam with ID:', examId);
    // Implement editing logic here (e.g., open a modal or navigate to an edit page)
  };

  return (
    <div>
      <h1>Manage Exam Data</h1>

      {/* Franchise filter dropdown */}
      <div>
        <label htmlFor="filterFranchiseId">Filter by Franchise:</label>
        <select
          id="filterFranchiseId"
          name="filterFranchiseId"
          value={filterFranchiseId}
          onChange={(e) => {
            const selectedFranchiseId = e.target.value;
            setFilterFranchiseId(selectedFranchiseId);

            // Fetch exam data for the selected franchise
            if (selectedFranchiseId) {
              const exams = getFranchiseExams(selectedFranchiseId);
              setExamDataList(exams);
            } else {
              setExamDataList([]);
            }
          }}
        >
          <option value="">All</option>
          {franchises.map((franchise) => (
            <option key={franchise._id} value={franchise._id}>
              {franchise.name}
            </option>
          ))}
        </select>
      </div>

      <h2>Exam Data</h2>
      {examDataList.length > 0 ? (
        <table border="1">
          <thead>
            <tr>
              <th>Franchise Name</th>
              <th>Exam Name</th>
              <th>Date</th>
              <th>Students Attended</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {examDataList.map((exam, index) => (
              <tr key={index}>
                <td>{getFranchiseName(exam.franchiseId)}</td>
                <td>{exam.examName}</td>
                <td>{exam.date}</td>
                <td>{exam.studentsAttended}</td>
                <td>
                  <button onClick={() => handleEditExam(exam._id)}>Edit</button>
                  <button onClick={() => handleDeleteExam(exam._id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No exam data available for the selected franchise.</p>
      )}
    </div>
  );
};

export default ExamData;
